"""PL-02 step 4: annualize volatility (spine: daily values pass through)."""

from __future__ import annotations

from dataclasses import replace

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """The same volatility marked annualized; the spine leaves the values daily."""
    del periods_per_year
    if vol.annualized:
        raise ValueError("vol is already annualized")
    return replace(vol, annualized=True)
