from __future__ import annotations

import pytest

from risk.annualize import annualize
from risk.types import Returns, VolSeries


def _daily() -> VolSeries:
    returns = Returns(
        base_date="2024-03-04",
        dates=("2024-03-05", "2024-03-06", "2024-03-07"),
        tickers=("AAPL",),
        values={"AAPL": (0.01, 0.03, -0.01)},
    )
    return VolSeries(
        returns=returns, window=2, annualized=False, values={"AAPL": (None, None, 0.02)}
    )


def test_marks_the_series_annualized():
    vol = annualize(_daily())
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns == _daily().returns


def test_spine_passes_daily_values_through():
    assert annualize(_daily()).values == {"AAPL": (None, None, 0.02)}


def test_already_annualized_is_an_error():
    with pytest.raises(ValueError, match="already annualized"):
        annualize(annualize(_daily()))
"""Intent tests for risk.annualize (RISK-03, TC-06): volatility annualized over trading days."""

from __future__ import annotations

from typing import Any

import pytest

from risk.annualize import annualize
from risk.types import Returns, VolSeries


def _returns(payload: dict[str, Any]) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _vol(payload: dict[str, Any]) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _assert_values_match(
    actual: dict[str, tuple[float | None, ...]],
    expected: dict[str, list[float | None]],
    tol: float,
) -> None:
    assert set(actual) == set(expected)
    for ticker, want in expected.items():
        got = actual[ticker]
        assert len(got) == len(want), ticker
        for i, (g, w) in enumerate(zip(got, want, strict=True)):
            if w is None:
                assert g is None, f"{ticker}[{i}] should stay a gap"
            else:
                assert g is not None, f"{ticker}[{i}] should not be a gap"
                assert g == pytest.approx(w, abs=tol), f"{ticker}[{i}]"


@pytest.mark.intent
def test_tc06_each_value_scaled_by_sqrt_252_and_gaps_kept(golden):
    inp, expected = golden("risk", "TC-06")
    vol = _vol(inp["vol"])

    out = annualize(vol)

    assert out.annualized is expected["annualized"]
    _assert_values_match(dict(out.values), expected["values"], expected["tol"])


@pytest.mark.intent
def test_tc06_keeps_returns_and_window(golden):
    inp, _ = golden("risk", "TC-06")
    vol = _vol(inp["vol"])

    out = annualize(vol)

    assert out.returns == vol.returns
    assert out.window == vol.window


@pytest.mark.intent
def test_tc06_default_is_252_trading_days(golden):
    inp, expected = golden("risk", "TC-06")
    vol = _vol(inp["vol"])

    explicit = annualize(vol, periods_per_year=252)

    _assert_values_match(dict(explicit.values), expected["values"], expected["tol"])
    assert dict(annualize(vol).values) == dict(explicit.values)


@pytest.mark.intent
def test_periods_per_year_changes_the_scale(golden):
    inp, expected = golden("risk", "TC-06")
    vol = _vol(inp["vol"])

    out = annualize(vol, periods_per_year=1)

    assert out.annualized is True
    _assert_values_match(dict(out.values), inp["vol"]["values"], expected["tol"])


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error(contract_sample):
    already = _vol(contract_sample("risk.VolSeries"))
    assert already.annualized is True

    with pytest.raises(ValueError, match="annualized"):
        annualize(already)


@pytest.mark.intent
def test_annualizing_twice_is_a_value_error(golden):
    inp, _ = golden("risk", "TC-06")
    once = annualize(_vol(inp["vol"]))

    with pytest.raises(ValueError, match="annualized"):
        annualize(once)
"""risk contract types: Returns, VolSeries."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass


def _check_series(
    tickers: tuple[str, ...], values: Mapping[str, Sequence[object]], length: int
) -> None:
    """Exactly one series per ticker, each `length` long."""
    if set(values) != set(tickers):
        raise ValueError("values must have exactly one entry per ticker")
    for ticker in tickers:
        if len(values[ticker]) != length:
            raise ValueError(f"{ticker}: one value per date required")


@dataclass(frozen=True)
class Returns:
    """Daily returns: `dates` are the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]

    def __post_init__(self) -> None:
        if list(self.dates) != sorted(set(self.dates)):
            raise ValueError("dates must be strictly ascending")
        if self.dates and self.base_date >= self.dates[0]:
            raise ValueError("base_date must come before the first date")
        if list(self.tickers) != sorted(set(self.tickers)):
            raise ValueError("tickers must be sorted and unique")
        _check_series(self.tickers, self.values, len(self.dates))


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]

    def __post_init__(self) -> None:
        if self.window < 2:
            raise ValueError("window must be at least 2")
        _check_series(self.returns.tickers, self.values, len(self.returns.dates))
        for ticker, series in self.values.items():
            if any(value is not None for value in series[: self.window]):
                raise ValueError(f"{ticker}: None until {self.window} earlier returns exist")
            if any(value is None for value in series[self.window :]):
                raise ValueError(f"{ticker}: a value once {self.window} earlier returns exist")
